#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(LFO_CTX_IN.len(), 54);
    assert_eq!(LFO_CTX_OUT.len(), LFO_CTX_IN.len());
    assert_eq!(LFO_FRAMES_IN.len(), 24);
    assert_eq!(LFO_FRAMES_OUT.len(), LFO_FRAMES_IN.len());
    assert!(LFO_FRAMES_IN != LFO_FRAMES_OUT);
}
